let state=readState(), catalog={words:[],collections:[]}, catalogMap=new Map(), catalogReady=false;
let ui={libraryTab:'all',query:'',level:'all',readerTab:'practice',translation:true,chunks:true,mode:'learn',libraryFilter:'all',reviewFilter:'due',wordTab:'mine',wordKind:'all',wordQuery:'',wordPage:0,showWordMeanings:true,onlineItems:[],onlineNotice:'',importText:'',importTitle:'',importSource:null,preview:null,attempt:null,reviewQ:null,started:Date.now(),helped:false,highlight:[],revealed:[],timer:null};
let sessionAI={provider:'deepseek',apiKey:''}, serviceStatus=null, activeLookup=null, readingSequence=0, speechText='', toastTimer;
