const glyph={grid:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',book:'<path d="M3 4h6a4 4 0 0 1 3 1.5A4 4 0 0 1 15 4h6v15h-6a4 4 0 0 0-3 1.5A4 4 0 0 0 9 19H3Z"/><path d="M12 6v14"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4Z"/>',words:'<path d="m3 17 5-12 5 12M5 13h6m4-4h6m-4-3v3c0 5-1 7-4 9m2-6c1 3 3 5 6 6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',plus:'<path d="M12 4v16M4 12h16"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',speaker:'<path d="m11 5-5 4H3v6h3l5 4Z"/><path d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',stop:'<rect x="5" y="5" width="14" height="14"/>',check:'<path d="m4 12 5 5L20 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-6 6-6 12 0 18M12 3c6 6 6 12 0 18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',close:'<path d="m5 5 14 14M5 19 19 5"/>',back:'<path d="M20 12H5m6-6-6 6 6 6"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14Z"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 4H3v17h17v-7"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${glyph[name]||glyph.book}</svg>`;
const attr=e;
const button=(label,action,extra='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const num=n=>String(n).padStart(2,'0');
const allPassages=()=>[...seedPassages.map(normalizePassage),...state.imported];
const passageById=id=>allPassages().find(p=>p.id===id);
const route=()=>{const r=location.hash.replace(/^#\/?/,'').split('/');return {page:paths[r[0]]?r[0]:'home',id:decodeURIComponent(r.slice(1).join('/'))};};
const current=()=>passageById(route().id);
const questionKey=(p,q)=>`${p.id}:${q.id}`;
const dueQuestions=()=>Object.entries(state.saved).filter(([,r])=>r&&isDue(r.schedule));
const languageItems=()=>Object.entries(state.words).filter(([,r])=>r&&r.entry);
const dueWords=()=>languageItems().filter(([,r])=>isDue(r.schedule));
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return true;}catch{toast('浏览器存储空间不足或不可用，请立即导出学习备份。');return false;}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4200);}
function go(page,id=''){location.hash=`#/${page}${id?'/'+encodeURIComponent(id):''}`;}
function markDay(){const day=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());state.days[day]=true;}
function showModal(title,body,actions='',english=false){modal.innerHTML=`<div class="modal-head"><h2 id="modal-title" class="${english?'english':''}">${e(title)}</h2><button type="button" data-action="close-modal" aria-label="关闭弹窗">×</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}`;if(!modal.open)modal.showModal();}
function shell(content,page){
 const due=dueQuestions().length+dueWords().length;
 app.innerHTML=`<div class="app-main"><header class="topbar"><a class="site-brand" href="#/home" aria-label="阅读工坊首页"><strong>Reading Lab.</strong><span>阅读工坊</span></a><nav class="primary-nav" aria-label="主导航">${[['home','工作台'],['library','精读题库'],['review','难题复习'],['words','学习词库'],['profile','学习设置']].map(([p,label])=>`<a href="#/${p}" ${page===p?'aria-current="page"':''}>${label}${p==='review'&&due?`<sup class="nav-count">${due}</sup>`:''}</a>`).join('')}</nav><a class="header-import" href="#/import"><span>导入阅读</span>${icon('external')}</a></header><main id="main" tabindex="-1">${content}</main></div>`;
 updateSpeakingBar();
}
function footer(){return `<footer class="footer-note"><span><strong class="footer-name">Every sentence matters.</strong>从一个词开始，建立自己的理解。<br>学习记录保存在本浏览器，可在学习设置中备份。</span><span>READING LAB. / 阅读工坊<br>WORDS IN BLOOM<br><button type="button" class="text-link" data-action="about" style="font-size:11px;margin-top:8px">关于与开源说明 ↗</button></span></footer>`;}
function materialCard(p,index){
 const done=(state.attempts[p.id]||[]).length;
 return `<article class="material-card"><span class="card-index">(${num(index+1)})</span><div class="material-kind"><strong>${e(p.level)}阅读</strong><span>${p.sourceType==='user'?'用户提供材料':p.sourceType==='original'?'原创练习 · 非真题':'我的导入'}${done?' · 已练习':''}</span></div><div class="material-info"><h3>${e(p.title)}</h3><p class="cn">${e(p.titleZh||p.topic)}</p></div><span class="metadata">${wordsCount(p)} WORDS<br>${p.paragraphs.length} 段 / ${p.questions.length} 道题</span><button type="button" class="round-link" data-action="start" data-id="${attr(p.id)}" aria-label="开始阅读 ${attr(p.title)}">${icon('arrow')}</button></article>`;
}
function renderHome(){
 const st=statistics(state),rec=recommendation(state),p=allPassages().find(p=>!state.attempts[p.id]?.length)||allPassages()[0];
 const due=dueQuestions().length+dueWords().length;
 shell(`<div class="page home-page"><section class="editorial-hero" aria-label="从看懂到读懂"><div class="hero-photo"><img src="/reading/editorial-book.png" alt="黑白光影中的书页与纸张纹理" width="1536" height="1024" fetchpriority="high"><div class="photo-caption"><span class="index">(01)</span><span><strong>Reading as a practice.</strong>以理解为起点。</span><span>WORDS IN BLOOM<br>READING LAB.</span></div></div><div class="hero-copy"><div class="hero-kicker"><span>ENGLISH READING<br>从每一种基础开始。</span><span>READ. LISTEN.<br>UNDERSTAND.</span></div><div class="hero-heading"><h1>从看懂，<br>到读懂。</h1><p class="hero-description">拆开一句英文，听清每个词。<br>让词义、语法和原文证据，<br>慢慢连成自己的理解。</p><div class="hero-actions">${button('开始学习 '+icon('arrow'),'start',`data-id="${attr(p.id)}"`)}<span class="quiet">零基础友好 / 按你的节奏</span></div></div><div class="hero-word" aria-hidden="true">Read.</div></div></section><div class="home-content"><section class="learning-index" aria-label="个人学习概览"><div class="index-intro"><strong>你的学习，逐渐累积。</strong>THE LEARNING INDEX<br>每一次理解，都留下痕迹。</div><div class="index-stat"><span class="value">${num(st.completed)}<span class="unit">篇</span></span><span class="label">完成阅读<br>Completed</span></div><div class="index-stat"><span class="value">${st.accuracy===null?'—':st.accuracy+'%'}<span class="unit">${st.total?'':'待练习'}</span></span><span class="label">首次独立正确率<br>Accuracy</span></div><div class="index-stat"><span class="value">${num(due)}<span class="unit">条</span></span><span class="label">到期题目与词条<br>Due for review</span></div></section><section class="continue-row"><span class="row-index">01</span><div class="row-kicker">继续阅读<span class="muted">CONTINUE<br>AT YOUR PACE.</span></div><div class="continue-title"><h2>${e(p.title)}</h2><p class="cn">${e(p.titleZh)}</p><div class="metadata"><span>${e(p.level)}阅读</span><span>${wordsCount(p)} 词</span><span>${p.paragraphs.length} 段</span><span>${p.questions.length} 道题</span></div></div><button type="button" class="round-link" data-action="start" data-id="${attr(p.id)}" aria-label="继续阅读 ${attr(p.title)}">${icon('arrow')}</button></section><section class="learning-spaces" aria-label="学习入口"><div class="spaces-header"><span>以理解为中心。</span><span>YOUR LEARNING SPACE / 01—03</span></div><a class="space-row" href="#/library"><span class="n">(01)</span><span class="space-name" lang="en">Reading.</span><span class="space-copy">精读与练习<small>逐句拆解，回到原文寻找答案。</small></span><span class="space-arrow" aria-hidden="true">↗</span></a><a class="space-row" href="#/words"><span class="n">(02)</span><span class="space-name" lang="en">Language.</span><span class="space-copy">词语与结构<small>${languageItems().length} 条单词、短语与语法，形成自己的学习库。</small></span><span class="space-arrow" aria-hidden="true">↗</span></a><a class="space-row" href="#/review"><span class="n">(03)</span><span class="space-name" lang="en">Recall.</span><span class="space-copy">回忆与复习<small>按记忆安排温习，把理解留得更久。</small></span><span class="space-arrow" aria-hidden="true">↗</span></a></section><div class="section-heading"><h2><span class="index">02 /</span> 阅读索引</h2><a class="text-link" href="#/library">全部阅读 ${icon('arrow')}</a></div><div class="materials">${allPassages().slice(0,3).map(materialCard).join('')}</div><section class="recommendation"><div class="recommend-label"><i class="square"></i>你的下一小步</div><div><h3>${e(skillLabels[rec.skill])} ${rec.tentative?'<span class="tag">暂定建议</span>':''}</h3><p>${e(rec.text)}</p><p>${e(rec.basis)}</p></div><a class="text-link" href="#/profile">调整学习画像 ${icon('arrow')}</a></section>${footer()}</div></div>`,'home');
}
function renderLibrary(){let list=allPassages().filter(p=>(ui.libraryFilter==='all'||(ui.libraryFilter==='import'?['import','web'].includes(p.sourceType):p.level===ui.libraryFilter))&&(p.title+' '+p.titleZh+' '+p.topic).toLowerCase().includes(ui.query.toLowerCase()));shell(`<div class="page"><div class="page-heading"><div><div class="eyebrow">THE READING COLLECTION</div><h1>精读题库</h1><p>先读懂，再读快。保留每篇材料的来源与答案状态。</p></div><span class="heading-index">COLLECTION / ${num(allPassages().length)}</span></div><div class="pill-tabs" role="tablist" aria-label="题库范围"><button role="tab" aria-selected="${ui.libraryTab==='all'}" class="${ui.libraryTab==='all'?'active':''}" data-action="library-tab" data-tab="all">我的阅读</button><button role="tab" aria-selected="${ui.libraryTab==='online'}" class="${ui.libraryTab==='online'?'active':''}" data-action="library-tab" data-tab="online">联网找材料 ${icon('external')}</button></div>${ui.libraryTab==='online'?onlinePanel():`<div class="toolbar"><label class="search">${icon('search')}<input id="library-search" placeholder="搜索标题、主题…" value="${attr(ui.query)}" aria-label="搜索阅读材料"></label><select id="library-filter" aria-label="筛选阅读材料"><option value="all">全部材料</option><option value="基础" ${ui.libraryFilter==='基础'?'selected':''}>基础阅读</option><option value="进阶" ${ui.libraryFilter==='进阶'?'selected':''}>进阶阅读</option><option value="import" ${ui.libraryFilter==='import'?'selected':''}>我的导入</option></select></div><div class="materials" id="materials-list">${list.length?list.map(materialCard).join(''):'<div class="empty"><h3>没有找到材料</h3><p>换一个关键词，或者导入自己的文章。</p></div>'}</div>`}${footer()}</div>`,'library');}
const resourceLinks=[{title:'历年考研英语真题索引',source:'中国教育在线 · 转载及参考答案需自行核对',url:'https://kaoyan.eol.cn/shiti/yingyu/',level:'考研英语一 / 英语二'},{title:'B1 Reading · 基础拓展',source:'British Council LearnEnglish · 含阅读与练习',url:'https://learnenglish.britishcouncil.org/free-resources/reading/b1',level:'B1'},{title:'B2 Reading · 进阶拓展',source:'British Council LearnEnglish · 含阅读与练习',url:'https://learnenglish.britishcouncil.org/free-resources/reading/b2',level:'B2'},{title:'English learning activities',source:'Cambridge English · 按能力选择练习',url:'https://www.cambridgeenglish.org/learning-english/activities-for-learners/',level:'综合英语'}];
function onlinePanel(){const items=ui.onlineItems.length?ui.onlineItems:resourceLinks;return `<div class="notice">连接真实来源查找阅读材料。网页导入后先校对正文、题目与答案；图片题和需要登录的内容，请从原站手动复制文本。原创题、参考答案与真题来源分别标明。</div><div class="toolbar"><label class="search">${icon('search')}<input id="online-query" aria-label="联网检索关键词" placeholder="主题词或年份，例如 technology / 2024" value="${attr(ui.onlineQuery||'')}"></label>${button(`${icon('globe')} 联网更新`,'discover','','primary')}</div><p class="session-status" id="online-status">${e(ui.onlineNotice||'下面是可直接访问的真实来源。点击“联网更新”获取来源网站的文章列表。')}</p><div id="online-list">${items.map((r,i)=>`<article class="source-card"><span class="source-n">${num(i+1)}</span><div><h3>${e(r.title)}</h3><p>${e(r.source)} ${r.level?' / '+e(r.level):''}</p><div class="source-url">${e(new URL(r.url).hostname)}</div></div><div class="source-actions"><a class="btn small ghost" href="${attr(safeURL(r.url))}" target="_blank" rel="noopener noreferrer">原站 ${icon('external')}</a>${button('导入网页','fetch-source',`data-url="${attr(r.url)}"`,'small')}</div></article>`).join('')}</div>`;}

function renderImport(){shell(`<div class="page"><div class="page-heading"><div><div class="eyebrow">BRING YOUR OWN READING</div><h1>导入一篇，慢慢读懂。</h1><p>粘贴文章与题目，或上传文本文件；识别后可以校对答案。</p></div><span class="heading-index">IMPORT / 01</span></div><div class="split-form"><section><div class="surface"><div class="form-field"><label for="import-title">阅读标题 <span class="muted small">选填</span></label><input class="field" id="import-title" value="${attr(ui.importTitle)}" placeholder="例如：Designing for Older Adults"></div><div class="form-field" style="margin-top:20px"><label for="import-text">英文文章与阅读题</label><textarea class="field editor" id="import-text" spellcheck="false" placeholder="Passage: Your reading title&#10;&#10;Paste the English passage here…&#10;&#10;1. What is the main idea?&#10;A. …&#10;B. …&#10;C. …&#10;D. …&#10;&#10;答案：1.B">${e(ui.importText)}</textarea><p class="hint">支持 TXT、Markdown、结构化 JSON；单次上限 1 MB。PDF或照片请先转成文字，避免图片内容漏题。</p></div><div class="form-actions">${button('识别并校对 '+icon('arrow'),'parse-import','','primary')}<label class="btn ghost">${icon('plus')} 上传文件<input id="import-file" type="file" accept=".txt,.md,.json,text/plain,application/json" hidden></label>${button('下载格式示例','download-template','','ghost')}</div><div id="import-error" class="error" role="alert"></div></div><div class="surface" style="margin-top:20px"><div class="form-field"><label for="source-url">或导入网页链接</label><div class="toolbar" style="margin:0"><input class="field" style="flex:1" id="source-url" type="url" placeholder="https://learnenglish.britishcouncil.org/…">${button('读取网页','fetch-url','','ghost')}</div><p class="hint">支持 British Council、中国教育在线、Cambridge English 的公开 HTTPS 页面。</p></div></div>${ui.preview?importPreview():''}</section><aside class="import-guide"><div class="eyebrow">A SMALL GUIDE</div><h3>先校对，再开始。</h3><ol><li>正文保留空行，方便识别段落。</li><li>题号使用 1.，选项 A—D 各占一行。</li><li>有参考答案可写在文末；没有答案，也能先收藏与精读。</li><li>完整双语解析需要连接模型；未连接时提供分句与结构线索。</li></ol><pre>Passage: Title\n\nParagraph one…\n\n1. Question?\nA. Option A\nB. Option B\nC. Option C\nD. Option D\n\n答案：1.B</pre><a class="text-link" href="#/profile">设置学习深度与模型 ${icon('arrow')}</a></aside></div>${footer()}</div>`,'import');}
function importPreview(){const p=ui.preview;return `<section class="surface import-preview" id="import-preview"><div class="eyebrow">CHECK BEFORE YOU START</div><h2 style="margin-top:10px">${e(p.title)}</h2><div class="preview-meta"><span class="tag">${p.paragraphs.length} 段</span><span class="tag">${flatten(p).length} 句</span><span class="tag">${p.questions.length} 道题</span><span class="tag">${wordsCount(p)} 词</span></div><div class="preview-content">${p.paragraphs.map(para=>`<p style="margin-bottom:12px">${e(para.map(s=>s.en).join(' '))}</p>`).join('')}</div>${p.questions.length?`<h3 style="font-size:12px;margin-top:20px">校对参考答案</h3><p class="session-status">未知答案可留空；未经核实的模型答案不计入正确率。请对照来源确认后再保存。</p><div class="answer-inputs">${p.questions.map((q,i)=>`<label>Q${i+1}<select class="preview-answer" data-index="${i}" aria-label="第${i+1}题参考答案"><option value="">未知</option>${'ABCD'.split('').map(a=>`<option ${q.answer===a?'selected':''}>${a}</option>`).join('')}</select></label>`).join('')}</div><div style="margin-top:15px"><label class="check-label"><input type="checkbox" id="confirm-answers" ${p.answerStatus!=='unverified'?'checked':''}>以上答案由我提供或已对照来源核实</label></div>`:''}<div class="form-actions">${button('保存并开始阅读','save-import','','primary')}${button('生成双语与逐题解析','ai-analyze','','ghost')}${button('返回修改','edit-import','','ghost')}</div><p class="ai-status" id="ai-status">${p.analysisMode==='ai'?'模型解析已生成，请核实答案与证据。':'未连接模型时不自动编造翻译或正确答案；可直接保存，使用分句、词典与朗读。'}</p></section>`;}

function draftFor(p){if(!state.drafts[p.id])state.drafts[p.id]={answers:{},confidence:{},helped:false};const d=state.drafts[p.id];if(!d.answers)d.answers={};if(!d.confidence)d.confidence={};return d;}
function tokenText(text,number=0,enabled=true){return String(text).split(/([A-Za-z]+(?:['’\-][A-Za-z]+)*)/).map((t,i)=>i%2?`<span class="word-token ${(state.words['word:'+t.toLowerCase()]||state.words['grammar:'+t.toLowerCase()])?'saved-word':''}" ${enabled?`role="button" tabindex="0" data-action="word" data-word="${attr(t)}" data-sentence="${number}" aria-label="查看 ${attr(t)} 的意思与用法"`:''}>${e(t)}</span>`:e(t)).join('');}
function listenButton(text,extra='',label='朗读英文'){return `<button type="button" class="icon-button" data-action="speak" data-text="${attr(text)}" ${extra} aria-label="${attr(label)}" title="${attr(label)}">${icon('speaker')}</button>`;}
function renderReader(){const p=current();if(!p){go('library');return;}const ss=flatten(p),d=draftFor(p),result=ui.attempt;const exam=ui.mode==='exam'&&!result;const canStudy=!exam;const ready=p.questions.filter(q=>q.answer).length;let content='';
  if(ui.readerTab==='study'&&canStudy){ui.helped=true;d.helped=true;save();content=`<div class="notice">点任意英文词看意思与用法；点喇叭听单句。语法标签也能打开独立讲解并收藏。${p.analysisMode==='rules'?'这篇尚无完整双语解析，下面的语法属于自动结构线索。':''}</div><div class="toolbar"><label class="toggle"><input id="toggle-translation" type="checkbox" ${ui.translation?'checked':''}>显示中文</label><label class="toggle"><input id="toggle-chunks" type="checkbox" ${ui.chunks?'checked':''}>拆句与语法</label>${button('收藏划词 / 短语','selection','','small ghost')}<span class="session-status">${state.profile.depth==='detailed'?'入门详解':state.profile.depth==='brief'?'简洁讲解':'标准讲解'}</span></div>${ss.map(s=>sentenceCard(p,s)).join('')}`;}
  else if(ui.readerTab==='structure'&&canStudy){ui.helped=true;d.helped=true;save();content=structurePanel(p);}
  else {content=`${result?resultPanel(p,result):`<div class="notice ${exam?'warning':''}">${exam?'独立练习：先完成整篇，再查看中文、点读和解析。':'学习练习：可以点词查义、听句子；使用辅助后会单独标记，不计作首次独立正确率。'} ${p.answerStatus==='unverified'?'本篇答案待核实，不进行正确率评分。':''}</div>`}<div class="reading-layout"><section class="passage-panel"><div class="panel-title"><span>英文原文 <span class="muted small">/ 点击词语查义</span></span><span class="number">${p.paragraphs.length} PARAGRAPHS</span></div><div class="passage-body">${p.paragraphs.map((para,i)=>`<p class="passage-paragraph"><span class="paragraph-n">${num(i+1)}</span>${para.map(s=>{const n=ss.find(x=>x.en===s.en)?.number;return `<span id="evidence-${n}" class="inline-sentence ${ui.highlight.includes(n)?'highlight':''}">${tokenText(s.en,n,!exam)}${!exam?`<button type="button" class="inline-listen" data-action="speak" data-text="${attr(s.en)}" aria-label="朗读第${n}句">${icon('speaker')}</button>`:''}</span> `;}).join('')}</p>`).join('')}</div><div class="panel-title"><span class="muted small">${e(p.source)}</span>${p.sourceUrl?`<a class="text-link" href="${attr(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">来源 ${icon('external')}</a>`:''}</div></section><section class="question-panel" aria-label="阅读题">${(ui.reviewQ?p.questions.filter(q=>q.id===ui.reviewQ):p.questions).map((q,i)=>questionCard(p,q,p.questions.indexOf(q)+1,result,exam)).join('')||'<div class="empty"><h3>这篇暂时没有选择题</h3><p>可以进入逐句精读。导入时也能一并粘贴题目，连接模型后生成解析。</p></div>'}${p.questions.length?`<div class="submit-bar"><div class="progress-text">${result?'本次练习已保存':`已选 ${Object.keys(d.answers).filter(k=>!ui.reviewQ||k===ui.reviewQ).length} / ${ui.reviewQ?1:p.questions.length} 题`}<br><span id="elapsed">${result?'保留首次答案与信心记录':'计时 '+elapsed()}</span></div>${result?button('重新练习','retry','','small'):button('提交整篇 '+icon('arrow'),'submit','','primary')}</div>`:''}</section></div>`;}
  shell(`<div class="page reading-page"><a class="text-link" href="#/library">${icon('back')} 返回题库</a><div class="reader-heading"><div><div class="tag-row"><span class="tag blue">${e(p.level)}</span><span class="tag">${p.sourceType==='original'?'原创练习 · 非真题':p.sourceType==='user'?'用户提供材料':'我的导入'}</span>${p.answerStatus==='unverified'?'<span class="tag red">答案待核实</span>':''}</div><h1>${e(p.title)}</h1><p class="zh-title">${e(p.titleZh||p.topic)}</p></div><div class="reader-settings"><select id="voice-accent" aria-label="朗读口音"><option value="en-US" ${state.profile.accent==='en-US'?'selected':''}>美式英语</option><option value="en-GB" ${state.profile.accent==='en-GB'?'selected':''}>英式英语</option></select><select id="voice-rate" aria-label="朗读语速">${[0.5,0.65,0.75,0.85,1,1.25].map(n=>`<option value="${n}" ${Math.abs(n-state.profile.rate)<.02?'selected':''}>${n}× 语速</option>`).join('')}</select></div></div><div class="reader-meta"><span>${wordsCount(p)} WORDS</span><span>${p.paragraphs.length} 段 / ${ss.length} 句</span><span>${p.questions.length} 道题 / ${ready} 题有参考答案</span><span>${e(p.exam)}</span></div><div class="reading-tabs"><div class="pill-tabs" role="tablist" aria-label="阅读方式">${[['practice','阅读练习'],['study','逐句精读'],['structure','结构与词汇']].map(([tab,label])=>`<button role="tab" aria-selected="${ui.readerTab===tab}" class="${ui.readerTab===tab?'active':''}" data-action="reader-tab" data-tab="${tab}" ${!canStudy&&tab!=='practice'?'disabled':''}>${label}</button>`).join('')}</div><div class="read-controls">${!exam?`${button(icon('speaker')+' 全文朗读','read-all','','small ghost')}${button('停止','stop','','small ghost')}`:''}<select id="reading-mode" aria-label="练习模式" style="height:32px;font-size:11px;padding:4px"><option value="learn" ${ui.mode==='learn'?'selected':''}>辅助学习</option><option value="exam" ${ui.mode==='exam'?'selected':''}>独立练习</option></select></div></div>${content}${footer()}</div>`,'read');}
function elapsed(){const seconds=Math.floor((Date.now()-ui.started)/1000);return `${Math.floor(seconds/60)}:${num(seconds%60)}`;}
function sentenceCard(p,s){const showDetails=ui.chunks;return `<article class="sentence-card" id="sentence-${s.number}"><div class="sentence-head"><span class="sentence-id">P${s.paragraph} / SENTENCE ${num(s.number)}</span><div class="read-controls">${listenButton(s.en,'',`朗读第${s.number}句`)}${button('收藏句子','save-sentence',`data-sentence="${s.number}"`,'small ghost')}</div></div><div class="sentence-en english" lang="en">${tokenText(s.en,s.number)}</div>${ui.translation?`<p class="sentence-zh">${e(s.zh||'这句还没有中文翻译。可回到导入页连接模型生成，或在下面写下自己的理解。')}</p>`:''}${showDetails?`<div class="sentence-analysis">${s.chunks.length&&state.profile.depth!=='brief'?`<div class="eyebrow">READ IN CHUNKS / 分块理解</div><div class="chunks">${s.chunks.map((c,i)=>`<div class="chunk"><div class="en" lang="en">${tokenText(c.en,s.number)} ${listenButton(c.en,'','朗读词块')}</div><div class="zh">${e(c.zh)}</div><button class="text-link" data-action="save-chunk" data-sentence="${s.number}" data-index="${i}" style="font-size:9px">＋ 存为短语</button></div>`).join('')}</div>`:''}${(state.profile.depth==='brief'?s.grammar.slice(0,1):s.grammar).map((g,i)=>`<div class="grammar-item"><button class="tag blue" data-action="grammar" data-sentence="${s.number}" data-index="${i}" title="打开语法解释并收藏">${e(g.label)} ＋</button> ${e(g.detail)}</div>`).join('')||'<p class="session-status">试着先找“谁 / 什么”与“做什么 / 是什么”，再补上修饰信息。</p>'}</div>`:''}<textarea class="sentence-note" data-note="${attr(p.id+':'+s.number)}" rows="1" aria-label="第${s.number}句笔记" placeholder="写下自己的理解，自动保存…">${e(state.notes[p.id+':'+s.number]||'')}</textarea></article>`;}
function questionCard(p,q,i,result,exam){const d=draftFor(p),a=result?.answers?.[q.id],chosen=result?a?.choice:d.answers[q.id],graded=!!a&&a.correct!==null&&a.correct!==undefined;return `<article class="question-card" id="question-${q.id}"><div class="question-top"><span class="question-number">QUESTION ${num(i)} <span style="margin-left:8px">${e(q.type)}</span></span><button type="button" class="icon-button ${state.saved[questionKey(p,q)]?'on':''}" data-action="save-question" data-qid="${q.id}" aria-label="${state.saved[questionKey(p,q)]?'取消收藏':'收藏难题'}" title="收藏难题">${icon('bookmark')}</button></div><div class="question-stem" lang="en">${e(q.stem)}${!exam&&state.profile.level==='beginner'&&q.stemZh?`<span class="translation" lang="zh-CN">${e(q.stemZh)}</span>`:''}</div><div class="options">${q.options.map((opt,j)=>{const letter='ABCD'[j];return `<label class="option ${chosen===letter?'selected':''} ${graded&&q.answer===letter?'correct':''} ${graded&&chosen===letter&&!a.correct?'wrong':''}"><input type="radio" name="${attr(p.id+'-'+q.id)}" value="${letter}" data-question="${q.id}" ${chosen===letter?'checked':''} ${result?'disabled':''}><span class="option-letter">${letter}</span><span>${e(opt)}${result&&q.optionsZh[j]?`<span class="option-zh" lang="zh-CN">${e(q.optionsZh[j])}</span>`:''}</span></label>`;}).join('')}</div>${!result?`<div class="confidence"><span>你对这一题有把握吗？</span><div class="confidence-options">${[['low','有点猜'],['medium','不太确定'],['high','有把握']].map(([v,label])=>`<button type="button" class="${(d.confidence[q.id]||'medium')===v?'active':''}" data-action="confidence" data-qid="${q.id}" data-value="${v}">${label}</button>`).join('')}</div></div>`:questionAnalysis(p,q,a)}</article>`;}
function questionAnalysis(p,q,a){const unknown=p.answerStatus==='unverified'||!q.answer;return `<div class="question-analysis"><div class="answer-label"><strong>${unknown?'待核实答案':a.correct?'回答正确':'需要再看一看'}</strong><span class="tag ${a.correct?'blue':'red'}">${unknown?'暂不计分':`参考答案 ${q.answer}`} / 你的选择 ${e(a.choice)}</span></div>${unknown?'<p>当前没有经过确认的参考答案。请对照来源校对后再评分，不能把模型推断当成官方答案。</p>':`<p>${e(q.explanation||'这题尚无完整解析，请回到原文对照你的答案与参考答案。')}</p>`}${q.evidence.length?`<div class="evidence-links">${q.evidence.map(n=>`<button type="button" class="evidence-link" data-action="evidence" data-sentence="${n}">定位证据 S${num(n)} ↗</button>`).join('')}</div>`:''}${q.paraphrase.length?`<details class="analysis-detail" ${state.profile.depth==='detailed'?'open':''}><summary>原文与选项怎样对应？</summary>${q.paraphrase.map(v=>`<p class="small" style="margin-top:9px"><span class="english">${e(v.original)}</span> → <span class="english">${e(v.option)}</span></p>`).join('')}</details>`:''}${q.distractors.length?`<details class="analysis-detail" ${state.profile.depth==='detailed'?'open':''}><summary>四个选项为什么对 / 错？</summary><ul>${q.distractors.map((v,i)=>`<li><strong>${'ABCD'[i]}.</strong> ${e(v)}</li>`).join('')}</ul></details>`:''}<div class="cause-select"><label for="cause-${q.id}">可能错因，可自行修正</label><select id="cause-${q.id}" data-cause="${q.id}">${Object.entries(skillLabels).map(([k,v])=>`<option value="${k}" ${(a.cause||q.skill)===k?'selected':''}>${v}</option>`).join('')}</select></div>${ui.reviewQ===q.id?`<p class="small muted" style="margin-top:15px">理解证据后，按真实回忆情况评分：</p><div class="review-ratings">${ratingsHTML('rate-question',`data-key="${attr(questionKey(p,q))}"`)}</div>`:''}</div>`;}
function ratingsHTML(action,extra){return [['again','没记住'],['hard','较吃力'],['good','记住了'],['easy','很轻松']].map(([rating,label])=>`<button class="rating ${rating}" data-action="${action}" data-rating="${rating}" ${extra}>${label}</button>`).join('');}
function resultPanel(p,a){const answers=Object.values(a.answers),known=answers.filter(q=>q.correct!==null),right=known.filter(q=>q.correct).length;return `<section class="result-strip"><div><span class="eyebrow">${a.helped?'ASSISTED PRACTICE / 辅助练习':'INDEPENDENT PRACTICE / 独立练习'}</span><p style="margin-top:9px">${known.length?`答对 ${right} / ${known.length} 题；${answers.length-known.length} 题待核实。`:'答案待核实，本次仅记录选择。'} 错题和低信心题已加入复习本。</p></div><strong>${known.length?Math.round(right/known.length*100)+'%':'—'}</strong></section>`;}
function structurePanel(p){return `<div class="structure-grid"><section><div class="summary-box"><h3>MAIN IDEA / 全文主旨</h3><p>${e(p.summary||'这篇尚无主旨解析。先尝试回答：文章在讨论谁、什么问题、作者主张什么？')}</p></div><div class="surface"><h2>段落怎样连起来？</h2>${p.structure.length?p.structure.map((s,i)=>`<div class="structure-row"><span class="number">${num(i+1)}</span><div><h3>${e(s.label)}</h3><p>${e(s.description)}</p></div></div>`).join(''):p.paragraphs.map((_,i)=>`<div class="structure-row"><span class="number">${num(i+1)}</span><div><h3>第${i+1}段</h3><p>读完后，用一句话写出这一段的作用：提出问题、解释、举例、转折，还是总结？</p></div></div>`).join('')}</div></section><aside class="surface"><h2>本篇词汇与表达</h2><p class="session-status">点击词语看详细用法，收藏后可按单词、短语和语法分类温习。</p>${p.vocabulary.map((v,i)=>`<div class="word-phrase"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><button class="text-link english" style="font-size:18px" data-action="vocab-item" data-index="${i}">${e(v.word)}</button>${listenButton(v.word)}</div><p class="small"><span class="muted">${e(v.pos)}</span> ${e(v.meaning)}</p>${v.phrase?`<p class="small muted">${e(v.phrase)}</p>`:''}</div>`).join('')||'<p class="session-status" style="margin-top:20px">点击原文单词即可查词并加入学习库。完整词汇整理可在导入页连接模型生成。</p>'}</aside></div>`;}

function renderReview(){const entries=Object.entries(state.saved).filter(([,r])=>r&&(ui.reviewFilter!=='due'||isDue(r.schedule)));const languages=languageItems().filter(([,r])=>ui.reviewFilter!=='due'||isDue(r.schedule));shell(`<div class="page"><div class="page-heading"><div><div class="eyebrow">RETURN. RECALL. UNDERSTAND.</div><h1>难题与复习</h1><p>收藏值得重看的内容。复习时先回忆，再核对证据与解释。</p></div><span class="heading-index">FSRS / SPACED REPETITION</span></div><div class="toolbar"><div class="pill-tabs" style="margin:0;flex:1"><button class="${ui.reviewFilter==='due'?'active':''}" data-action="review-filter" data-value="due">今日到期 ${dueQuestions().length+dueWords().length}</button><button class="${ui.reviewFilter==='all'?'active':''}" data-action="review-filter" data-value="all">全部收藏 ${Object.keys(state.saved).length+languageItems().length}</button></div>${button('导出学习备份','backup','','small ghost')}</div><div class="notice">复习日期由 FSRS 根据你的回忆评分调整。首次学习可能在几分钟后再次出现；“答对”与“真正记住”分别记录。低信心答对也值得巩固。</div><div class="section-heading"><h2><span class="index">01 /</span> 阅读难题</h2><span class="small muted">${entries.length} 道</span></div>${entries.length?entries.map(([key,r])=>{const p=passageById(r.passageId),q=p?.questions.find(q=>q.id===r.qid);if(!q)return '';return `<article class="review-card"><div class="review-top"><span class="tag ${isDue(r.schedule)?'red':''}">${e(dueLabel(r.schedule))}</span><span class="small muted">${e(r.reason||'主动收藏')} / ${e(skillLabels[r.cause||q.skill])}</span></div><h3>${e(q.stem)}</h3><p class="review-title">${e(p.title)}</p><div class="review-bottom"><span class="note">${r.schedule?.reps?`已复习 ${r.schedule.reps} 次`:'首次复习'} · 先选答案，再定位证据</span><div class="read-controls">${button('移出收藏','remove-question',`data-key="${attr(key)}"`,'small ghost')}${button('回忆这道题 '+icon('arrow'),'review-question',`data-key="${attr(key)}"`,'small primary')}</div></div></article>`;}).join(''):'<div class="empty"><h3>这里暂时没有到期难题</h3><p>练习后的错题、低信心题，以及主动收藏的题目会出现在这里。</p><a class="btn small" href="#/library">去读一篇文章</a></div>'}<div class="section-heading"><h2><span class="index">02 /</span> 单词 · 短语 · 语法</h2><a class="text-link" href="#/words">整理学习库 ${icon('arrow')}</a></div>${languages.length?`<div class="word-grid">${languages.slice(0,15).map(([key,r])=>`<article class="word-card"><div class="word-top"><h3 class="${r.kind==='grammar'?'':'english'}">${e(r.entry.word)}</h3><span class="tag">${kindLabel(r.kind)}</span></div><p class="session-status">${e(dueLabel(r.schedule))}</p><div class="form-actions" style="margin-top:15px">${button('先回忆，再揭晓','review-word',`data-key="${attr(key)}"`,'small primary')}</div></article>`).join('')}</div>`:'<p class="session-status">还没有到期词条。在原文点词或语法标签，就能分类收藏。</p>'}${footer()}</div>`,'review');}

function kindLabel(kind){return {word:'单词',phrase:'短语',grammar:'语法'}[kind]||'单词';}
function renderWords(){const mine=ui.wordTab==='mine';let list=mine?languageItems().filter(([,r])=>(ui.wordKind==='all'||r.kind===ui.wordKind)&&(r.entry.word+' '+(r.entry.meaning||r.entry.core||'')).toLowerCase().includes(ui.wordQuery.toLowerCase())):catalog.words.filter(w=>(w.word+' '+w.meaning).toLowerCase().includes(ui.wordQuery.toLowerCase())).map(w=>['word:'+w.word.toLowerCase(),{entry:catalogEntry(w),kind:'word'}]);const total=list.length,pageSize=24;ui.wordPage=Math.max(0,Math.min(ui.wordPage,Math.max(0,Math.ceil(total/pageSize)-1)));list=list.slice(ui.wordPage*pageSize,(ui.wordPage+1)*pageSize);shell(`<div class="page"><div class="page-heading"><div><div class="eyebrow">WORDS CONNECTED TO READING</div><h1>把不懂的，留在学习库。</h1><p>单词记核心义，短语记搭配，语法记结构。收藏时一并保留原句。</p></div>${button(icon('plus')+' 添加词条','new-entry','','small')}</div><div class="pill-tabs"><button class="${mine?'active':''}" data-action="word-tab" data-tab="mine">我的学习库 ${languageItems().length}</button><button class="${!mine?'active':''}" data-action="word-tab" data-tab="catalog">词间日和词库 ${catalogReady?catalog.words.length:'…'}</button></div><div class="toolbar"><label class="search">${icon('search')}<input id="word-search" placeholder="搜索英文、中文含义或语法名称…" aria-label="搜索学习词条" value="${attr(ui.wordQuery)}"></label>${mine?`<select id="word-kind" aria-label="词条分类">${[['all','全部分类'],['word','单词'],['phrase','短语'],['grammar','语法']].map(([k,v])=>`<option value="${k}" ${ui.wordKind===k?'selected':''}>${v}</option>`).join('')}</select>`:''}<label class="toggle"><input id="show-meanings" type="checkbox" ${ui.showWordMeanings?'checked':''}>显示释义</label></div>${!mine?`<div class="notice">与原站共用同一份 40 个词集、2,557 个单词和点读模块。这里提供简洁阅读视图；<a href="/index.html" target="_blank" rel="noopener">打开原词间日和</a> 可继续使用原有词集、记忆卡片和学习进度。</div>`:''}<div class="word-grid">${list.map(([key,r])=>wordCard(key,r,mine)).join('')}</div>${!list.length?`<div class="empty"><h3>${mine?'学习库还在等待你的第一个词':'没有匹配的词条'}</h3><p>在逐句精读中点一个词，或点语法标签，就能查看解释、听发音并分类收藏。</p><a class="btn small" href="#/library">打开一篇阅读</a></div>`:''}${total>pageSize?`<div class="pagination">${button('上一页','word-page','data-delta="-1"','small ghost')}<span>${ui.wordPage+1} / ${Math.ceil(total/pageSize)}</span>${button('下一页','word-page','data-delta="1"','small ghost')}</div>`:''}${footer()}</div>`,'words');}
function wordCard(key,r,mine){const v=r.entry;return `<article class="word-card"><div class="word-top"><h3 class="${r.kind==='grammar'?'':'english'}"><button style="text-align:left;font:inherit;padding:0" data-action="open-entry" data-key="${attr(key)}" data-word="${attr(v.word)}">${e(v.word)}</button></h3><div class="word-actions">${/[A-Za-z]/.test(v.word)?listenButton(v.word):''}<button class="icon-button ${state.words[key]?'on':''}" data-action="${mine?'remove-entry':'save-catalog'}" data-key="${attr(key)}" data-word="${attr(v.word)}" aria-label="${mine?'移出学习库':'收藏到学习库'}">${icon('bookmark')}</button></div></div><p class="phonetic">${e(v.pos||kindLabel(r.kind))} ${e(v.phonetic||'')} ${mine?' / '+e(dueLabel(r.schedule)):''}</p>${ui.showWordMeanings?`<p class="meaning">${e(v.meaning||v.core||'尚无释义，可打开后联网查询或手动补充。')}</p>${v.examples?.[0]?`<div class="example" lang="en">${e(v.examples[0].en||v.examples[0].sentence)} ${listenButton(v.examples[0].en||v.examples[0].sentence)}</div><p class="example-zh">${e(v.examples[0].zh||v.examples[0].translation||'')}</p>`:''}`:'<p class="meaning muted">先试着回忆它的意思与用法。</p>'}${mine?`<div class="form-actions" style="margin-top:15px">${button('回忆复习','review-word',`data-key="${attr(key)}"`,'small ghost')}<span class="tag">${kindLabel(r.kind)}</span></div>`:''}</article>`;}
function catalogEntry(w){return {word:w.word,meaning:w.meaning,core:w.meaning,pos:w.pos,phonetic:w.phonetic,usage:(w.collocations||[]).map(x=>x.phrase+'：'+x.meaning).join('；'),examples:(w.examples||[]).map(x=>({en:x.sentence,zh:x.translation})),phrases:(w.collocations||[]).map(x=>({en:x.phrase,zh:x.meaning})),source:'词间日和本地词库'};}
function findEntry(word){const lower=word.toLowerCase().replace(/’/g,"'");if(basicDictionary.has(lower))return {...basicDictionary.get(lower)};let seed=allPassages().flatMap(p=>p.vocabulary).find(v=>v.word.toLowerCase()===lower);if(seed)return {word:seed.word,pos:seed.pos,meaning:seed.meaning,core:seed.meaning,usage:seed.phrase,examples:[],phrases:seed.phrase?[{en:seed.phrase,zh:''}]:[],source:'本篇词汇讲解'};let candidates=[lower,lower.replace(/'s$/,''),lower.replace(/ies$/,'y'),lower.replace(/s$/,''),lower.replace(/es$/,''),lower.replace(/ed$/,''),lower.replace(/ed$/,'e'),lower.replace(/ing$/,''),lower.replace(/ing$/,'e')];let w=candidates.map(k=>catalogMap.get(k)).find(Boolean);return w?catalogEntry(w):{word,meaning:'',core:'',usage:'',examples:[],phrases:[],source:'本地词库尚无此词'};}
function wordBody(entry,context,reveal=true){if(!reveal)return `<p>先回忆：它的核心含义是什么？在原句里起什么作用？</p>${context?.en?`<div class="word-detail-example">${e(context.en)}</div>`:''}${button('想好后，揭晓解释','reveal-entry','','primary')}`;return `<div class="word-pronounce"><span class="muted">${e(entry.pos||'')} ${e(entry.phonetic||'')}</span>${/[A-Za-z]/.test(entry.word)?listenButton(entry.word,'','朗读词条'):''}</div><h3>核心含义</h3><p>${e(entry.meaning||entry.core||'本地词库暂未收录。你可以联网查词，或手动填写解释。')}</p>${entry.contextMeaning?`<h3>当前语境中的意思</h3><p>${e(entry.contextMeaning)}</p>`:''}${context?.en?`<h3>回到原句</h3><div class="word-detail-example" lang="en">${e(context.en)} ${listenButton(context.en)}</div>${context.zh?`<p class="muted small" style="margin-top:8px">${e(context.zh)}</p>`:''}`:''}${entry.usage?`<h3>怎么使用</h3><p>${e(entry.usage)}</p>`:''}${entry.examples?.length?`<h3>例句与点读</h3>${entry.examples.slice(0,3).map(x=>`<div class="word-detail-example" lang="en">${e(x.en||x.sentence)} ${listenButton(x.en||x.sentence)}</div><p class="muted small">${e(x.zh||x.translation||'')}</p>`).join('')}`:''}${entry.phrases?.length?`<h3>常见搭配</h3>${entry.phrases.slice(0,5).map((x,i)=>`<div class="word-phrase"><span class="english">${e(x.en)}</span> ${listenButton(x.en)} <span class="muted">${e(x.zh)}</span>${button('存为短语','lookup-phrase',`data-index="${i}"`,'small ghost')}</div>`).join('')}`:''}<p class="source-credit">${e(entry.source||'个人学习词条')}${!entry.contextMeaning&&entry.kind!=='grammar'?'。以上是参考义；结合原句与中文对照判断此处含义。':''}</p>`;}
function openWord(word,context=null,entry=null,kind=null,key=null,review=false){activeLookup={entry:entry||findEntry(word),context,kind:kind||(basicDictionary.has(word.toLowerCase())?'grammar':word.includes(' ')?'phrase':'word'),key,review,reveal:!review};renderWordModal();}
function renderWordModal(){if(!activeLookup)return;const a=activeLookup,v={...a.entry,kind:a.kind};showModal(v.word,wordBody(v,a.context,a.reveal)+(a.reveal&&!a.review?`<div class="form-field" style="margin-top:20px"><label for="entry-kind">收藏分类</label><select id="entry-kind">${['word','phrase','grammar'].map(k=>`<option value="${k}" ${a.kind===k?'selected':''}>${kindLabel(k)}</option>`).join('')}</select></div>`:'')+(a.review&&a.reveal?`<p class="small muted" style="margin-top:20px">按真实回忆情况选择，系统会调整下次复习日期。</p><div class="review-ratings">${ratingsHTML('rate-word',`data-key="${attr(a.key)}"`)}</div>`:''),a.review?'':`${button('收藏到学习库','save-lookup','','primary')}${button('手动补充 / 修改','edit-entry','','ghost')}${/^[A-Za-z][A-Za-z'’-]{0,69}$/.test(v.word)?button('联网查词','lookup-online','','ghost'):''}`,/^[A-Za-z]/.test(v.word)&&v.word.length<45);}
function saveEntry(entry,kind,context=null,key=null){const id=key||`${kind}:${entry.word.toLowerCase().trim()}`;if(id.length>250){toast('词条标题过长，请缩短后收藏。');return;}const old=state.words[id];const examples=[...new Map([...(old?.entry?.examples||[]),...(entry.examples||[])].filter(x=>x?.en||x?.sentence).map(x=>[x.en||x.sentence,x])).values()].slice(-15);state.words[id]={entry:{...entry,examples,word:String(entry.word).slice(0,200)},kind,context:context||old?.context||null,schedule:old?.schedule||null,createdAt:old?.createdAt||new Date().toISOString()};markDay();save();toast(`已收藏到「${kindLabel(kind)}」`);return id;}
function editEntry(entry=null,kind='word',key=null,context=null){const v=entry||{word:'',meaning:'',usage:''};activeLookup={entry:v,kind,key,context};showModal(entry?'整理这个词条':'添加学习词条',`<div class="form-grid"><div class="form-field wide"><label for="custom-word">单词 / 短语 / 语法名称</label><input class="field" id="custom-word" value="${attr(v.word)}" maxlength="200"></div><div class="form-field wide"><label for="custom-meaning">核心含义或语法解释</label><textarea class="field" id="custom-meaning">${e(v.meaning||v.core||'')}</textarea></div><div class="form-field wide"><label for="custom-usage">用法、搭配或记忆提醒</label><textarea class="field" id="custom-usage">${e(v.usage||'')}</textarea></div><div class="form-field"><label for="custom-kind">分类</label><select id="custom-kind">${['word','phrase','grammar'].map(k=>`<option value="${k}" ${k===kind?'selected':''}>${kindLabel(k)}</option>`).join('')}</select></div></div>`,button('保存词条','save-custom','','primary'));}

function renderProfile(){const p=state.profile,st=statistics(state),rec=recommendation(state);shell(`<div class="page"><div class="page-heading"><div><div class="eyebrow">YOUR PACE. YOUR WAY.</div><h1>从你现在的位置开始。</h1><p>零基础可以慢慢拆，有基础可以少一点提示。随时调整。</p></div><span class="heading-index">LEARNER / PROFILE</span></div><div class="profile-grid"><section><form class="surface" id="profile-form"><h2>我的学习画像</h2><div class="form-grid" style="margin-top:23px"><div class="form-field"><label for="profile-level">目前阅读基础</label><select id="profile-level" name="level"><option value="beginner" ${p.level==='beginner'?'selected':''}>入门 / 零基础优先</option><option value="intermediate" ${p.level==='intermediate'?'selected':''}>有基础 / 巩固提高</option><option value="advanced" ${p.level==='advanced'?'selected':''}>进阶 / 考试训练</option></select></div><div class="form-field"><label for="profile-exam">学习目标</label><select name="exam" id="profile-exam">${['英语一','英语二','综合英语'].map(v=>`<option ${p.exam===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="form-field"><label for="profile-target">目标分数</label><input class="field" id="profile-target" type="number" name="target" min="0" max="100" value="${p.target}"><p class="hint">个人目标，不根据单篇练习预测考试分数。</p></div><div class="form-field"><label for="profile-minutes">每天可用时间 / 分钟</label><input class="field" id="profile-minutes" name="minutes" type="number" min="10" max="180" value="${p.minutes}"></div><div class="form-field wide"><label for="profile-depth">讲解深度</label><select name="depth" id="profile-depth"><option value="detailed" ${p.depth==='detailed'?'selected':''}>入门详解：中英对照、词块、语法与选项分析</option><option value="standard" ${p.depth==='standard'?'selected':''}>标准：逐句翻译与主要结构</option><option value="brief" ${p.depth==='brief'?'selected':''}>简洁：保留主要语法，按需展开</option></select></div><div class="form-field wide"><span class="form-label">目前最想解决的困难</span><div class="checkboxes">${Object.entries(skillLabels).map(([k,v])=>`<label class="check-label"><input type="checkbox" name="focus" value="${k}" ${p.focus.includes(k)?'checked':''}>${v}</label>`).join('')}</div></div><div class="form-field"><label for="profile-accent">朗读口音</label><select id="profile-accent" name="accent"><option value="en-US" ${p.accent==='en-US'?'selected':''}>美式英语</option><option value="en-GB" ${p.accent==='en-GB'?'selected':''}>英式英语</option></select></div><div class="form-field"><label for="profile-rate">朗读速度</label><select id="profile-rate" name="rate">${[0.5,0.65,0.75,0.85,1,1.25].map(n=>`<option value="${n}" ${Math.abs(n-p.rate)<.02?'selected':''}>${n}× ${n===.5?'逐句慢听':n===.85?'推荐':''}</option>`).join('')}</select></div></div><div class="form-actions"><button class="btn primary" type="submit">保存学习设置 ${icon('check')}</button>${button(icon('speaker')+' 试听发音','speak','data-text="Learning begins with understanding one sentence."','ghost')}</div></form><section class="surface" style="margin-top:22px"><h2>任意文章的智能解析</h2><p class="session-status">内置三篇练习已提供完整讲解。新文章的语境词义、双语翻译与逐题解析，需要模型接口；未连接时，导入、分句、朗读、本地词库与复习仍可使用。</p><div class="form-grid" style="margin-top:18px"><div class="form-field"><label for="ai-provider">模型服务</label><select id="ai-provider"><option value="deepseek" ${sessionAI.provider==='deepseek'?'selected':''}>DeepSeek</option><option value="openai" ${sessionAI.provider==='openai'?'selected':''}>OpenAI</option></select></div><div class="form-field"><label for="ai-key">API 密钥 <span class="muted small">仅本次会话</span></label><input class="field" id="ai-key" type="password" autocomplete="off" placeholder="输入密钥，或使用已配置的服务端密钥" value="${attr(sessionAI.apiKey)}"></div></div><div class="form-actions">${button('应用到本次会话','configure-ai','','ghost')}</div><p class="session-status" id="model-status" style="margin-top:12px">${e(serviceStatus?.notice||'正在检查服务端配置…')}</p><p class="session-status" style="margin-top:8px">模型生成时会将文章发送到所选服务；密钥不写入浏览器存储或学习备份。费用由所选服务按其规则计算。离开或刷新页面后需重新输入。朗读优先使用设备语音，设备不可用时联网合成当前朗读文本。</p></section><section class="surface" style="margin-top:22px"><h2>备份与恢复</h2><p class="session-status">本浏览器自动保存。换设备或清理数据前，导出一份备份；备份包含阅读、词条、笔记与原站词汇进度，不含模型密钥。</p><div class="data-actions">${button(icon('download')+' 导出完整备份','backup','','ghost')}<label class="btn ghost">恢复备份<input id="restore-file" type="file" accept=".json,application/json" hidden></label><a class="btn ghost" href="/index.html" target="_blank" rel="noopener">原词间日和 ${icon('external')}</a></div></section></section><aside><section class="surface"><div class="eyebrow">LEARNING SIGNALS</div><h2 style="margin-top:12px">我的练习线索</h2><p class="session-status">只看已练习内容，不用一次测试定义你的能力。</p><div class="skill-chart">${Object.entries(st.skills).map(([k,v])=>`<div class="skill-row"><span>${e(skillLabels[k])}</span><div class="skill-bar"><i style="width:${v.total?Math.round((v.total-v.wrong)/v.total*100):0}%"></i></div><span class="skill-value">${v.total?v.total-v.wrong+'/'+v.total:'暂无样本'}</span></div>`).join('')}</div><p class="session-status">${e(rec.basis)}</p></section><section class="import-guide" style="display:block;margin-top:23px"><div class="eyebrow">A GENTLE START</div><h3>每天 ${p.minutes} 分钟，从小处练。</h3><ol><li>约 ${Math.max(3,Math.round(p.minutes*.2))} 分钟：回忆到期词条与难题。</li><li>约 ${Math.round(p.minutes*.55)} 分钟：读一段原文，点词、听句、拆主干。</li><li>约 ${Math.max(3,Math.round(p.minutes*.25))} 分钟：完成题目，找出证据，只整理一项主要困难。</li></ol><p>词义和语法收藏，是为了下次能独立认出它。</p></section></aside></div>${footer()}</div>`,'profile');}

const speech=createSpeechController({allowReadingOnline:true,onStateChange:s=>{speechText=s.speaking?s.text:'';updateSpeakingBar();},onError:({message})=>toast(message)});
speech.setAccent(state.profile.accent);speech.setRate(state.profile.rate);
function updateSpeakingBar(){document.querySelector('.speaking-bar')?.remove();document.querySelectorAll('[data-action="speak"]').forEach(b=>b.classList.toggle('playing',!!speechText&&b.dataset.text===speechText));if(speechText){const bar=document.createElement('div');bar.className='speaking-bar';bar.setAttribute('role','status');bar.innerHTML=`<span class="mono">NOW READING</span><span class="text" lang="en">${e(speechText)}</span><button type="button" data-action="stop">${icon('stop')} 停止</button>`;document.body.append(bar);}}
function stopReading(){readingSequence++;speech.stop();}
function helpUsed(){if(route().page==='read'&&current()&&!ui.attempt){ui.helped=true;draftFor(current()).helped=true;save();}}
function speak(text){if(ui.mode==='exam'&&route().page==='read'&&!ui.attempt){toast('完成独立练习后即可点读。');return;}helpUsed();readingSequence++;speech.speak(text,{lang:state.profile.accent,rate:state.profile.rate});}
function readAll(){const p=current();if(!p)return;helpUsed();const seq=++readingSequence,ss=flatten(p);let index=0;const next=()=>{if(seq!==readingSequence||index>=ss.length)return;const s=ss[index++];speech.speak(s.en,{lang:state.profile.accent,rate:state.profile.rate,onEnd:next});};next();}
function startReading(id,{reviewQ=null,independent=false}={}){const p=passageById(id);if(!p)return;stopReading();ui.attempt=null;ui.reviewQ=reviewQ;ui.readerTab=reviewQ||independent?'practice':state.profile.level==='beginner'?'study':'practice';ui.mode=independent?'exam':'learn';ui.helped=false;ui.highlight=[];ui.started=Date.now();if(reviewQ)state.drafts[p.id]={answers:{},confidence:{},helped:false};if(route().page==='read'&&route().id===id)renderReader();else go('read',id);}
function submitAnswers(){const p=current();if(!p||ui.attempt)return;const d=draftFor(p),qs=ui.reviewQ?p.questions.filter(q=>q.id===ui.reviewQ):p.questions;const missing=qs.find(q=>!d.answers[q.id]);if(missing){toast('还有题目未选择，完成整篇后再提交。');document.querySelector('#question-'+missing.id)?.scrollIntoView({behavior:'smooth',block:'center'});return;}const answers={};for(const q of qs){const known=!!q.answer&&p.answerStatus!=='unverified';answers[q.id]={choice:d.answers[q.id],correct:known?d.answers[q.id]===q.answer:null,confidence:d.confidence[q.id]||'medium',skill:q.skill,cause:q.skill};const a=answers[q.id];if(known&&(!a.correct||a.confidence==='low')){const key=questionKey(p,q),old=state.saved[key];state.saved[key]={...old,passageId:p.id,qid:q.id,reason:!a.correct?'答错待巩固':'低信心答对',cause:q.skill,schedule:old?.schedule||null,createdAt:old?.createdAt||new Date().toISOString()};}}
  const a={id:`attempt-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,at:new Date().toISOString(),answers,seconds:Math.floor((Date.now()-ui.started)/1000),mode:ui.reviewQ?'review':ui.mode,helped:ui.mode!=='exam'||ui.helped||d.helped};(state.attempts[p.id]||=([])).push(a);ui.attempt=a;delete state.drafts[p.id];markDay();save();renderReader();document.querySelector('.result-strip')?.scrollIntoView({behavior:'smooth',block:'start'});}
function toggleQuestion(qid){const p=current(),q=p?.questions.find(x=>x.id===qid);if(!q)return;const key=questionKey(p,q);if(state.saved[key]){delete state.saved[key];toast('已移出难题收藏');}else{state.saved[key]={passageId:p.id,qid:q.id,reason:'主动收藏',cause:q.skill,schedule:null,createdAt:new Date().toISOString()};toast('已加入难题收藏');}save();renderReader();}
async function api(path,body){const response=await fetch(`/api/reading/${path}`,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(95000),cache:'no-store'});let data;try{data=await response.json();}catch{throw new Error('服务暂时不可用，请稍后重试。');}if(!response.ok)throw new Error(data.error||'请求没有完成，请稍后重试');return data;}
async function fetchSource(url,el){const error=document.querySelector('#import-error');try{if(!url)throw new Error('请填写来源网址');if(el){el.disabled=true;el.textContent='正在读取…';}const data=await api('fetch',{url});ui.importText=`Passage: ${data.title}\n\n${data.text}`;ui.importTitle=data.title;ui.importSource=data;ui.preview=null;go('import');if(route().page==='import')renderImport();toast(data.notice||'已读取来源网页，请校对正文和题目。');}catch(err){if(error)error.textContent=err.message;else toast(err.message);}finally{if(el?.isConnected){el.disabled=false;el.textContent='导入网页';}}}
function snapshotPreview(){if(!ui.preview)return;document.querySelectorAll('.preview-answer').forEach(el=>ui.preview.questions[Number(el.dataset.index)].answer=el.value||null);const checked=document.querySelector('#confirm-answers');if(checked)ui.preview.answerStatus=checked.checked?'verified':'unverified';}
async function analyzeImport(el){snapshotPreview();const p=ui.preview;if(!p)return;const status=document.querySelector('#ai-status');try{el.disabled=true;status.textContent='正在生成双语、拆句和证据解析，可能需要约一分钟…';const text=`${p.paragraphs.map(para=>para.map(s=>s.en).join(' ')).join('\n\n')}\n\n${p.questions.map((q,i)=>`${i+1}. ${q.stem}\n${q.options.map((o,j)=>'ABCD'[j]+'. '+o).join('\n')}`).join('\n\n')}${p.answerStatus==='verified'?'\n答案：'+p.questions.map((q,i)=>q.answer?(i+1)+'.'+q.answer:'').filter(Boolean).join(' '):''}`;const result=await api('analyze',{text,title:p.title,profile:state.profile,...sessionAI});const parsed=normalizePassage(result.passage);const norm=t=>t.replace(/\s+/g,' ').trim();if(norm(flatten(parsed).map(s=>s.en).join(' '))!==norm(flatten(p).map(s=>s.en).join(' ')))throw new Error('模型返回的原文发生变化，已停止保存。请重试或使用原始材料。');if(parsed.questions.length!==p.questions.length)throw new Error('模型返回的题目数量与原始材料不一致，已停止保存。');for(let i=0;i<p.questions.length;i++){if(norm(parsed.questions[i].stem)!==norm(p.questions[i].stem)||parsed.questions[i].options.some((o,j)=>norm(o)!==norm(p.questions[i].options[j])))throw new Error('模型改变了原题或选项，已停止保存。');}ui.preview={...parsed,id:p.id,source:p.source,sourceUrl:p.sourceUrl,sourceType:p.sourceType,analysisMode:'ai',answerStatus:'unverified'};renderImport();document.querySelector('#import-preview')?.scrollIntoView({behavior:'smooth'});toast('解析已生成。请核实参考答案后保存。');}catch(err){status.textContent=err.message;}finally{if(el.isConnected)el.disabled=false;}}
function downloadJSON(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function backup(){let legacy=null;try{legacy=JSON.parse(localStorage.getItem('wordsInBloomData')||'null');}catch{}downloadJSON(`reading-lab-backup-${new Date().toISOString().slice(0,10)}.json`,{format:'reading-lab-backup',version:1,exportedAt:new Date().toISOString(),reading:state,legacyVocabulary:legacy});toast('已导出备份，不包含模型密钥。');}
let pendingBackup=null;
async function prepareRestore(file){try{if(!file)return;if(file.size>8000000)throw new Error('备份超过8MB，请检查文件');const data=JSON.parse(await file.text());const reading=validateState(data.reading||data);pendingBackup={reading,legacyVocabulary:data.legacyVocabulary};showModal('合并这份学习备份？',`<p>识别到 ${reading.imported.length} 篇导入文章、${Object.keys(reading.words).length} 条学习词条和 ${Object.keys(reading.saved).length} 道难题。</p><p>将保留当前资料，并合并备份内容。相同词条使用备份中的版本；历史练习按记录ID去重。</p>${data.legacyVocabulary?'<label class="check-label"><input type="checkbox" id="restore-legacy">同时恢复原词间日和的词汇进度（替换该部分现有进度）</label>':''}`,button('合并备份','apply-restore','','primary')+button('取消','close-modal','','ghost'));}catch(err){toast('备份未恢复：'+err.message);}}
function applyRestore(){if(!pendingBackup)return;const b=pendingBackup.reading;const merged={...state,profile:b.profile,imported:[...new Map([...state.imported,...b.imported].map(p=>[p.id,p])).values()],attempts:{...state.attempts},drafts:{...state.drafts,...b.drafts},saved:{...state.saved,...b.saved},words:{...state.words,...b.words},notes:{...state.notes,...b.notes},days:{...state.days,...b.days}};for(const [id,arr]of Object.entries(b.attempts)){if(Array.isArray(arr))merged.attempts[id]=[...new Map([...(merged.attempts[id]||[]),...arr].filter(a=>a&&a.id).map(a=>[a.id,a])).values()];}try{const checked=document.querySelector('#restore-legacy')?.checked;if(checked&&pendingBackup.legacyVocabulary)localStorage.setItem('wordsInBloomData',JSON.stringify(pendingBackup.legacyVocabulary));state=validateState(merged);save();modal.close();pendingBackup=null;speech.setAccent(state.profile.accent);speech.setRate(state.profile.rate);render();toast('备份已合并。');}catch{toast('未能恢复，请检查浏览器存储空间。');}}

document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,p=current();try{switch(a){
case 'start':startReading(el.dataset.id);break;
case 'close-modal':modal.close();break;
case 'about':showModal('关于阅读工坊',`<p>一个为入门读者设计的英语阅读学习空间，与词间日和词库融合。</p><p>文章导入、逐句双语、证据解析、点词学习和间隔复习共同服务于“看得懂、听得清、下次能独立理解”。</p><h3>开源模块与参考</h3><p>复习调度采用 <a href="https://github.com/open-spaced-repetition/ts-fsrs" target="_blank" rel="noopener">ts-fsrs</a>（MIT）。曾评估 Lute、Readest、Exameow，未直接使用其整站源码。词库与原点读代码来自现有词间日和项目。</p><p><a href="/vendor/fsrs/NOTICE.md" target="_blank">FSRS版本与许可说明</a> · <a href="/vendor/fsrs/LICENSE" target="_blank">MIT License</a></p><p class="muted small">学习数据保存在当前浏览器；模型解析需要API服务，模型推断答案标为待核实。此站不宣称原创材料是考研真题。</p>`);break;
case 'library-tab':ui.libraryTab=el.dataset.tab;renderLibrary();break;
case 'discover':{ui.onlineQuery=document.querySelector('#online-query').value.trim();el.disabled=true;el.textContent='正在联网…';document.querySelector('#online-status').textContent='正在读取来源网站的真实文章索引…';try{const data=await api('discover?query='+encodeURIComponent(ui.onlineQuery));ui.onlineItems=data.items;ui.onlineNotice=data.notice;renderLibrary();}catch(err){document.querySelector('#online-status').textContent=err.message;el.disabled=false;el.innerHTML=icon('globe')+' 联网更新';}break;}
case 'fetch-source':await fetchSource(el.dataset.url,el);break;
case 'fetch-url':await fetchSource(document.querySelector('#source-url').value.trim(),el);break;
case 'parse-import':{ui.importText=document.querySelector('#import-text').value;ui.importTitle=document.querySelector('#import-title').value.trim();try{ui.preview=parseReadingText(ui.importText,ui.importTitle);if(ui.importSource)Object.assign(ui.preview,{sourceUrl:ui.importSource.sourceUrl,source:ui.importSource.source,sourceType:'web'});renderImport();document.querySelector('#import-preview').scrollIntoView({behavior:'smooth'});}catch(err){document.querySelector('#import-error').textContent=err.message;}break;}
case 'edit-import':ui.preview=null;renderImport();document.querySelector('#import-text').focus();break;
case 'save-import':{snapshotPreview();const value=normalizePassage(ui.preview);if(!value)return;const at=state.imported.findIndex(p=>p.id===value.id);if(at>=0)state.imported[at]=value;else state.imported.push(value);if(!save())break;ui.preview=null;ui.importText='';ui.importTitle='';ui.importSource=null;startReading(value.id);toast('阅读材料已保存。');break;}
case 'ai-analyze':await analyzeImport(el);break;
case 'download-template':downloadJSON('reading-import-example.json',normalizePassage(seedPassages[0]));break;
case 'reader-tab':ui.readerTab=el.dataset.tab;stopReading();renderReader();break;
case 'speak':speak(el.dataset.text);break;
case 'read-all':readAll();break;
case 'stop':stopReading();break;
case 'word':{if(ui.mode==='exam'&&route().page==='read'&&!ui.attempt)break;helpUsed();const context=p?flatten(p).find(s=>s.number===Number(el.dataset.sentence)):null;openWord(el.dataset.word,context);break;}
case 'vocab-item':{const v=p?.vocabulary[Number(el.dataset.index)];if(v)openWord(v.word,null,{word:v.word,meaning:v.meaning,pos:v.pos,usage:v.phrase,phrases:[],examples:[],source:'本篇词汇讲解'});break;}
case 'grammar':{const s=flatten(p).find(x=>x.number===Number(el.dataset.sentence)),g=s?.grammar[Number(el.dataset.index)];if(g)openWord(g.label,s,{word:g.label,meaning:g.detail,usage:'阅读时先识别结构，再结合上下文判断含义。',examples:[{en:s.en,zh:s.zh}],phrases:[],source:'本篇语法讲解'},'grammar');break;}
case 'save-sentence':{const s=flatten(p).find(x=>x.number===Number(el.dataset.sentence));if(s)editEntry({word:s.en.length>170?s.en.slice(0,167)+'…':s.en,meaning:s.zh,usage:'原句：'+s.en,examples:[{en:s.en,zh:s.zh}],phrases:[],source:p.title},'phrase',null,s);break;}
case 'save-chunk':{const s=flatten(p).find(x=>x.number===Number(el.dataset.sentence)),c=s?.chunks[Number(el.dataset.index)];if(c)openWord(c.en,s,{word:c.en,meaning:c.zh,usage:'来自精读句子的词块，连同原句一起记忆。',examples:[{en:s.en,zh:s.zh}],phrases:[],source:p.title},'phrase');break;}
case 'selection':{const selected=window.getSelection()?.toString().trim();if(!selected||selected.length>180){toast('先在英文中选中一个词或短语，长度不超过180字符。');break;}const context=flatten(p).find(s=>s.en.includes(selected));openWord(selected,context,selected.includes(' ')?{word:selected,meaning:context?.chunks.find(c=>c.en===selected)?.zh||'',usage:'请结合原句填写这段表达的含义。',examples:context?[{en:context.en,zh:context.zh}]:[],phrases:[],source:p.title}:null,selected.includes(' ')?'phrase':'word');break;}
case 'save-lookup':{if(!activeLookup)break;const kind=document.querySelector('#entry-kind')?.value||activeLookup.kind;saveEntry(activeLookup.entry,kind,activeLookup.context);modal.close();if(route().page==='words')renderWords();break;}
case 'edit-entry':if(activeLookup)editEntry(activeLookup.entry,document.querySelector('#entry-kind')?.value||activeLookup.kind,activeLookup.key,activeLookup.context);break;
case 'new-entry':editEntry();break;
case 'save-custom':{const word=document.querySelector('#custom-word').value.trim(),meaning=document.querySelector('#custom-meaning').value.trim(),usage=document.querySelector('#custom-usage').value.trim(),kind=document.querySelector('#custom-kind').value;if(!word||!meaning){toast('请填写词条名称和核心解释。');break;}const v={...activeLookup.entry,word,meaning,core:meaning,usage};if(activeLookup.key&&activeLookup.kind!==kind)delete state.words[activeLookup.key];saveEntry(v,kind,activeLookup.context,activeLookup.kind===kind?activeLookup.key:null);modal.close();if(route().page==='words')renderWords();break;}
case 'lookup-online':{if(!activeLookup)break;const lookup=activeLookup;el.disabled=true;el.textContent='正在查词…';try{const data=await api('lookup',{word:lookup.entry.word,context:lookup.context?.en||'',...sessionAI});if(activeLookup===lookup&&modal.open){const incoming=data.entry;if(lookup.entry.meaning&&incoming.source?.startsWith('DictionaryAPI')){incoming.meaning=lookup.entry.meaning;incoming.core=lookup.entry.core||lookup.entry.meaning;incoming.usage=[lookup.entry.usage,incoming.usage].filter(Boolean).join('；');}lookup.entry={...lookup.entry,...incoming};renderWordModal();}}catch(err){toast(err.message);}finally{if(el.isConnected){el.disabled=false;el.textContent='联网查词';}}break;}
case 'lookup-phrase':{const x=activeLookup?.entry.phrases[Number(el.dataset.index)];if(x)saveEntry({word:x.en,meaning:x.zh,usage:'搭配来源：'+activeLookup.entry.word,examples:[],phrases:[],source:activeLookup.entry.source},'phrase',activeLookup.context);break;}
case 'confidence':{const d=draftFor(p);d.confidence[el.dataset.qid]=el.dataset.value;save();renderReader();break;}
case 'save-question':toggleQuestion(el.dataset.qid);break;
case 'submit':submitAnswers();break;
case 'retry':{state.drafts[p.id]={answers:{},confidence:{},helped:false};ui.attempt=null;ui.started=Date.now();ui.helped=false;ui.highlight=[];renderReader();save();break;}
case 'evidence':{ui.highlight=[Number(el.dataset.sentence)];renderReader();document.querySelector('#evidence-'+el.dataset.sentence)?.scrollIntoView({behavior:'smooth',block:'center'});break;}
case 'review-filter':ui.reviewFilter=el.dataset.value;renderReview();break;
case 'remove-question':delete state.saved[el.dataset.key];save();renderReview();toast('已移出难题收藏');break;
case 'review-question':{const r=state.saved[el.dataset.key];if(r)startReading(r.passageId,{reviewQ:r.qid});break;}
case 'rate-question':{const r=state.saved[el.dataset.key];if(!r)break;r.schedule=scheduleReview(r.schedule,el.dataset.rating);save();go('review');toast('下次复习：'+dueLabel(r.schedule));break;}
case 'word-tab':ui.wordTab=el.dataset.tab;ui.wordPage=0;renderWords();break;
case 'word-page':ui.wordPage+=Number(el.dataset.delta);renderWords();document.querySelector('#main').scrollIntoView();break;
case 'open-entry':{const r=state.words[el.dataset.key];if(r)openWord(r.entry.word,r.context,r.entry,r.kind,el.dataset.key);else openWord(el.dataset.word);break;}
case 'save-catalog':{const w=catalogMap.get(el.dataset.word.toLowerCase());if(w){saveEntry(catalogEntry(w),'word');renderWords();}break;}
case 'remove-entry':delete state.words[el.dataset.key];save();renderWords();toast('已移出学习库');break;
case 'review-word':{const r=state.words[el.dataset.key];if(r)openWord(r.entry.word,r.context,r.entry,r.kind,el.dataset.key,true);break;}
case 'reveal-entry':if(activeLookup){activeLookup.reveal=true;renderWordModal();}break;
case 'rate-word':{const r=state.words[el.dataset.key];if(r){r.schedule=scheduleReview(r.schedule,el.dataset.rating);markDay();save();modal.close();render();toast('下次复习：'+dueLabel(r.schedule));}break;}
case 'configure-ai':sessionAI={provider:document.querySelector('#ai-provider').value,apiKey:document.querySelector('#ai-key').value.trim()};toast(sessionAI.apiKey?'模型密钥已用于本次会话。':'已切换模型服务；如服务端未配置，需要输入密钥。');break;
case 'backup':backup();break;
case 'apply-restore':applyRestore();break;
}}catch(err){toast(err.message||'这一步没有完成，请重试。');}});

document.addEventListener('change',async ev=>{const el=ev.target,p=current();if(el.matches('[data-question]')&&p){draftFor(p).answers[el.dataset.question]=el.value;save();const text=document.querySelector('.submit-bar .progress-text');if(text)text.innerHTML=`已选 ${Object.keys(draftFor(p).answers).filter(k=>!ui.reviewQ||k===ui.reviewQ).length} / ${ui.reviewQ?1:p.questions.length} 题<br><span id="elapsed">计时 ${elapsed()}</span>`;document.querySelectorAll(`input[data-question="${el.dataset.question}"]`).forEach(r=>r.closest('.option').classList.toggle('selected',r.checked));}
  else if(el.id==='library-filter'){ui.libraryFilter=el.value;renderLibrary();}
  else if(el.id==='word-kind'){ui.wordKind=el.value;ui.wordPage=0;renderWords();}
  else if(el.id==='show-meanings'){ui.showWordMeanings=el.checked;renderWords();}
  else if(el.id==='toggle-translation'){ui.translation=el.checked;renderReader();}
  else if(el.id==='toggle-chunks'){ui.chunks=el.checked;renderReader();}
  else if(el.id==='voice-accent'){state.profile.accent=el.value;speech.setAccent(el.value);save();}
  else if(el.id==='voice-rate'){state.profile.rate=Number(el.value);speech.setRate(Number(el.value));save();}
  else if(el.id==='reading-mode'){stopReading();ui.mode=el.value;ui.readerTab='practice';ui.attempt=null;ui.helped=false;ui.started=Date.now();state.drafts[p.id]={answers:{},confidence:{},helped:false};save();renderReader();toast(ui.mode==='exam'?'已开始独立练习，讲解与点读将在提交后开放。':'已切换辅助学习模式。');}
  else if(el.matches('[data-cause]')&&ui.attempt){const a=ui.attempt.answers[el.dataset.cause];if(a){a.cause=el.value;const key=p.id+':'+el.dataset.cause;if(state.saved[key])state.saved[key].cause=el.value;save();}}
  else if(el.id==='import-file'){try{const f=el.files[0];if(!f)return;if(f.size>1000000)throw new Error('文件超过1MB，请分篇导入');ui.importText=await f.text();ui.importTitle=f.name.replace(/\.[^.]+$/,'');ui.importSource=null;ui.preview=null;renderImport();toast('文件已读取，请识别并校对。');}catch(err){toast(err.message);}}
  else if(el.id==='restore-file')await prepareRestore(el.files[0]);
});
let searchTimer;
document.addEventListener('input',ev=>{const el=ev.target;if(el.matches('[data-note]')){state.notes[el.dataset.note]=el.value.slice(0,4000);save();}if(el.id==='import-text'){ui.importText=el.value;ui.importSource=null;}if(el.id==='import-title')ui.importTitle=el.value;if(el.id==='library-search'||el.id==='word-search'){const position=el.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(el.id==='library-search'){ui.query=el.value;renderLibrary();}else{ui.wordQuery=el.value;ui.wordPage=0;renderWords();}const next=document.querySelector('#'+el.id);next?.focus();next?.setSelectionRange(position,position);},240);}});
document.addEventListener('submit',ev=>{if(ev.target.id!=='profile-form')return;ev.preventDefault();const fd=new FormData(ev.target);state.profile={...state.profile,level:fd.get('level'),exam:fd.get('exam'),target:Number(fd.get('target')),minutes:Number(fd.get('minutes')),depth:fd.get('depth'),focus:fd.getAll('focus'),accent:fd.get('accent'),rate:Number(fd.get('rate'))};state=validateState(state);save();speech.setAccent(state.profile.accent);speech.setRate(state.profile.rate);toast('学习设置已保存，下一次精读会按这个深度显示。');renderProfile();});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){stopReading();return;}if((ev.key==='Enter'||ev.key===' ')&&ev.target.matches('.word-token[data-action]')){ev.preventDefault();ev.target.click();}});
modal.addEventListener('click',ev=>{if(ev.target===modal){const r=modal.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)modal.close();}});
window.addEventListener('hashchange',()=>{stopReading();modal.close();render();window.scrollTo(0,0);});
window.addEventListener('pagehide',()=>{stopReading();save();});
function render(){const r=route();({home:renderHome,library:renderLibrary,import:renderImport,read:renderReader,review:renderReview,words:renderWords,profile:renderProfile}[r.page]||renderHome)();}
setInterval(()=>{const el=document.querySelector('#elapsed');if(el&&!ui.attempt)el.textContent='计时 '+elapsed();},1000);
render();
fetch('/data/catalog.json').then(r=>{if(!r.ok)throw new Error();return r.json();}).then(data=>{catalog=data;catalogMap=new Map(data.words.map(w=>[w.word.toLowerCase(),w]));catalogReady=true;if(route().page==='words')renderWords();}).catch(()=>toast('原站词库加载失败，刷新后可重试；已收藏词条仍可使用。'));
api('status').then(status=>{serviceStatus=status;const el=document.querySelector('#model-status');if(el)el.textContent=status.notice;}).catch(()=>{serviceStatus={configured:false,notice:'服务端配置暂不可用，可先使用内置讲解和本地学习功能。'};});
